  const SkyLinkApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(title: 'SkyLink Direct', debugShowCheckedModeBanner: false, theme: ThemeData.dark(useMaterial3: true).copyWith(scaffoldBackgroundColor: ink, colorScheme: const ColorScheme.dark(primary: blue, surface: panel), appBarTheme: const AppBarTheme(backgroundColor: ink, foregroundColor: Colors.white), inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: panel, border: OutlineInputBorder(borderRadius: BorderRadius.circular(10), borderSide: const BorderSide(color: Color(0xFF2A3A4C))), enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(10), borderSide: const BorderSide(color: Color(0xFF2A3A4C))))), home: const BootScreen());
}

class BootScreen extends StatefulWidget { const BootScreen({super.key}); @override State<BootScreen> createState() => _BootScreenState(); }
class _BootScreenState extends State<BootScreen> {
  final api = Api(); bool ready = false;
  @override void initState() { super.initState(); _boot(); }
  Future<void> _boot() async { final prefs = await SharedPreferences.getInstance(); api.token = prefs.getString('token'); if (mounted) setState(() => ready = true); }
  @override Widget build(BuildContext context) => !ready ? const Scaffold(body: Center(child: CircularProgressIndicator())) : api.token == null ? AuthScreen(api: api, onLogin: (token) async { final prefs = await SharedPreferences.getInstance(); await prefs.setString('token', token); api.token = token; if (mounted) setState(() {}); }) : HomeScreen(api: api, onLogout: () async { try { await api.call('/auth/logout', method: 'POST'); } catch (_) {} final prefs = await SharedPreferences.getInstance(); await prefs.remove('token'); api.token = null; if (mounted) setState(() {}); });
}

